  SUBS={};const free=[];sq.forEach(d=>{const v=Object.assign({id:d.id},d.data());SUBS[d.id]=v;if(!v.aid)free.push(v)});free.sort((a,b)=>b.ts-a.ts);ASG=A;
  const base={};(state.marks||[]).forEach(m=>base[m.id]=m);Object.keys(SUBS).forEach(k=>{const v=SUBS[k];if(v.marked&&v.score!=null)base[k]={id:k,score:+v.score}});state.marks=Object.keys(base).map(k=>base[k]);save();localStorage.rq_asg_t=Date.now();window.rqAsgDot=false;try{rqDotPaint()}catch(x){}
